// Builds the Service Portal bundle (UI script x_enno_pivot.pivot_portal) from the same workspace sources
// the UI page uses. No third-party bundler: each module is wrapped in its own function scope.
// Runs automatically before `now-sdk build` (see package.json "build").
import { readFileSync, writeFileSync, mkdirSync } from 'node:fs'
import { dirname, join } from 'node:path'
import { fileURLToPath } from 'node:url'

const root = join(dirname(fileURLToPath(import.meta.url)), '..')
const client = join(root, 'src', 'client')
const out = join(root, 'src', 'fluent', 'portal', 'generated', 'pivot-portal.bundle.js')
const modules = ['portal/bootstrap-reset.js', 'pivot/styles.js', 'pivot/shell.js', 'pivot/live-store.js', 'pivot/workspace.js']

// Service Portal loads Bootstrap 3 globally. To keep the approved design exact, every design rule is scoped
// under the id that the portal entry puts on <html> (#x_enno_pivot_html); one id outranks Bootstrap's class rules.
const SCOPE_ID = '#x_enno_pivot_html'
function splitTop(list) {
    const out = []; let depth = 0, cur = ''
    for (const ch of list) {
        if (ch === '(' || ch === '[') depth++
        if (ch === ')' || ch === ']') depth--
        if (ch === ',' && depth === 0) { out.push(cur); cur = '' } else cur += ch
    }
    out.push(cur); return out
}
function scopeSelector(sel) {
    sel = sel.trim()
    if (!sel) return sel
    if (/^(html|:root)$/.test(sel)) return SCOPE_ID
    if (/^(html|:root)[\s>:.\[]/.test(sel)) return SCOPE_ID + sel.replace(/^(html|:root)/, '')
    return SCOPE_ID + ' ' + sel
}
function scopeCss(css) {
    css = css.replace(/\/\*[\s\S]*?\*\//g, '')
    let i = 0, out = ''
    function block(scope) {
        while (i < css.length) {
            const open = css.indexOf('{', i), close = css.indexOf('}', i)
            if (close !== -1 && (open === -1 || close < open)) { out += css.slice(i, close + 1); i = close + 1; return }
            if (open === -1) { out += css.slice(i); i = css.length; return }
            const prelude = css.slice(i, open).trim()
            if (/^@(media|supports)/.test(prelude)) { out += prelude + '{'; i = open + 1; block(scope); continue }
            if (/^@/.test(prelude)) { // @keyframes, @font-face: copy the whole block unchanged
                let depth = 0, j = open
                for (; j < css.length; j++) { if (css[j] === '{') depth++; else if (css[j] === '}' && --depth === 0) break }
                out += prelude + css.slice(open, j + 1); i = j + 1; continue
            }
            const end = css.indexOf('}', open)
            out += (scope ? splitTop(prelude).map(scopeSelector).join(',') : prelude) + css.slice(open, end + 1)
            i = end + 1
        }
    }
    block(true)
    return out
}

function wrap(file) {
    let code = readFileSync(join(client, file), 'utf8').replace(/\r\n/g, '\n')
    if (file === 'pivot/styles.js') code = 'export const CSS = ' + JSON.stringify(scopeCss(JSON.parse(code.slice(code.indexOf('export const CSS = ') + 19, code.lastIndexOf(';'))))) + ';\n'
    if (/^\s*import\s/m.test(code)) throw new Error(file + ' must not import other modules')
    const names = []
    code = code.replace(/^export\s+(const|function|let)\s+([A-Za-z_$][\w$]*)/gm, (m, kind, name) => { names.push(name); return kind + ' ' + name })
    if (/^export\s/m.test(code)) throw new Error(file + ' has an export form the portal bundler does not support')
    return `  // ---- ${file}\n  const { ${names.join(', ')} } = (function () {\n${code}\n  return { ${names.join(', ')} };\n  })();\n`
}

const entry = readFileSync(join(client, 'portal', 'portal-entry.js'), 'utf8').replace(/\r\n/g, '\n')
const bundle = '/* PIVOT Service Portal bundle – generated by scripts/build-portal-bundle.mjs. Do not edit; edit src/client instead. */\n'
    + '(function () {\n  \'use strict\';\n' + modules.map(wrap).join('\n') + '  // ---- portal/portal-entry.js\n' + entry + '\n})();\n'
// ASCII only, so the script works whatever character set the instance serves it with
const ascii = bundle.replace(/[^\x00-\x7e]/g, (c) => '\\u' + c.charCodeAt(0).toString(16).padStart(4, '0'))
mkdirSync(dirname(out), { recursive: true })
writeFileSync(out, ascii, 'utf8')
console.log('[pivot] Portal bundle written: ' + out.replace(root, '.') + ' (' + ascii.length + ' bytes)')
